# -*- coding: utf-8 -*-
"""工作流执行引擎 —— DAG 调度 + 子代理并行 + 条件路由。

边路由(route): success=仅上游成功触发 / failure=仅上游失败触发 / always=成败都触发
扇入: join=all 等所有入边满足; join=any 任一入边满足即触发
"""
from __future__ import annotations
import asyncio, json, time, uuid
from typing import Any, Dict, List, Optional
from . import store

def validate_graph(nodes, edges):
    errs = []
    if not nodes: errs.append("至少需要一个节点"); return errs
    ids = [n.get("id") for n in nodes]
    if len(set(ids)) != len(ids): errs.append("节点 id 重复")
    for n in nodes:
        if not (n.get("title") or "").strip(): errs.append(f"节点 [{n.get('id')}] 缺少标题")
        if not (n.get("input") or "").strip(): errs.append(f"节点 [{n.get('id')}] 缺少输入任务")
    for e in edges:
        s, t = e.get("source"), e.get("target")
        if s not in ids or t not in ids: errs.append(f"边 {s}->{t} 引用了不存在的节点")
        elif s == t: errs.append("不允许自连边")
    adj = {}
    for e in edges:
        s, t = e.get("source"), e.get("target")
        if s in ids and t in ids: adj.setdefault(s, []).append(t)
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {i: WHITE for i in ids}
    def dfs(u):
        color[u] = GRAY
        for v in adj.get(u, []):
            if color[v] == GRAY or (color[v] == WHITE and dfs(v)): return True
        color[u] = BLACK; return False
    if any(color[i] == WHITE and dfs(i) for i in ids): errs.append("流程图存在环,不允许循环")
    if len(ids) > 1:
        und = {i: set() for i in ids}
        for e in edges:
            s, t = e.get("source"), e.get("target")
            if s in und and t in und: und[s].add(t); und[t].add(s)
        start = next(iter(ids)); seen = {start}; stack = list(und[start])
        while stack:
            x = stack.pop()
            if x in und and x not in seen: seen.add(x); stack.extend(und[x] - seen)
        if len(seen) != len(ids): errs.append("存在互不相连的多个流程分组")
    return errs

def _edge_ok(route, st):
    if route == "always": return st in ("done", "failed")
    if route == "failure": return st == "failed"
    return st == "done"

def _edge_dead(route, st):
    return (not _edge_ok(route, st)) and st in ("done", "failed", "stopped", "skipped")

def _incoming(wf):
    ins = {n["id"]: [] for n in wf["nodes"]}
    for e in wf.get("edges", []):
        s, t, r = e.get("source"), e.get("target"), (e.get("route") or "success")
        if s in ins and t in ins: ins[t].append((s, r))
    return ins

def assemble_message(node, upstream_outputs):
    parts = ["[Workflow system]\n你正在执行工作流中的一个节点。只关注当前节点任务;上游结果仅作为上下文。\n"]
    if upstream_outputs:
        parts.append("[Workflow upstream results]\n")
        for title, out in upstream_outputs:
            parts.append(f"[Upstream: {title}]\n{out.strip()}\n\n")
    parts.append(f"[Current task]\n{(node.get('input') or '').strip()}")
    return "\n".join(parts)

async def run_workflow(wf_id):
    wf = store.get_workflow(wf_id)
    if not wf: return None
    errs = validate_graph(wf.get("nodes", []), wf.get("edges", []))
    run_id = uuid.uuid4().hex[:12]
    if errs:
        store.save_run({"run_id": run_id, "workflow_id": wf_id, "status": "failed",
                        "error": ";".join(errs), "nodes": {}, "started_at": _ms(), "ended_at": _ms()})
        return run_id
    run = {"run_id": run_id, "workflow_id": wf_id, "status": "running", "error": None,
           "started_at": _ms(), "ended_at": None,
           "nodes": {n["id"]: {"status": "pending", "session_id": None, "output": None, "error": None}
                      for n in wf["nodes"]}}
    store.save_run(run)
    asyncio.get_event_loop().create_task(_execute(wf, run))
    return run_id

def _ms(): return int(time.time() * 1000)

def request_stop(run_id): return True

async def _execute(wf, run):
    ins = _incoming(wf)
    nodes = {n["id"]: n for n in wf["nodes"]}
    state = {"stop": False}

    async def exec_node(nid):
        node = nodes[nid]; rec = run["nodes"][nid]
        rec["status"] = "running"; store.save_run(run)
        if state["stop"]: rec["status"] = "stopped"; return
        join_mode = (node.get("join") or "all")
        edges = ins.get(nid, [])
        sat = [u for u, r in edges if _edge_ok(r, run["nodes"][u]["status"])]
        if join_mode == "any" and sat: sat = sat[:1]
        upstreams = [(nodes[u].get("title") or u, run["nodes"][u].get("output") or "") for u in sat]
        message = assemble_message(node, upstreams)
        timeout = int(node.get("timeout") or 900)
        try:
            from ..agents.tools.agent_management import build_agent_chat_request, collect_final_agent_chat_response, format_agent_chat_text
            agent = (node.get("agent") or "").strip()
            final_sid, payload, _x = build_agent_chat_request(agent, message, session_id=rec.get("session_id"))
            response_data = await asyncio.to_thread(collect_final_agent_chat_response, None, payload, agent, timeout)
            if not response_data: raise RuntimeError("(No response received)")
            text = format_agent_chat_text(response_data, session_id=final_sid) or ""
            if "SESSION:" in text:
                head, _, body = text.partition("\n")
                if "SESSION" in head:
                    sid = head.split("SESSION:")[-1].split("]")[0].split(" ")[0].strip()
                    rec["session_id"] = sid; text = body.strip()
            from ..agents.tools.agent_management import extract_agent_text_content
            if not extract_agent_text_content(response_data):
                rec["raw"] = json.dumps(response_data, ensure_ascii=False)[:1500]
            if text.startswith("ERROR") or text.startswith("(No response"): raise RuntimeError(text)
            rec["status"] = "done"; rec["output"] = text
        except asyncio.TimeoutError:
            rec["status"] = "failed"; rec["error"] = f"节点超时(>{timeout}s)"
        except Exception as exc:
            rec["status"] = "failed"; rec["error"] = str(exc)[:500]
        store.save_run(run)

    while True:
        if state["stop"]:
            for nid, rec in run["nodes"].items():
                if rec["status"] in ("pending", "running"): rec["status"] = "stopped"
            run["status"] = "stopped"; break
        def ready_check(nid):
            if run["nodes"][nid]["status"] != "pending": return False
            edges = ins.get(nid, [])
            if not edges: return True
            sat = [_edge_ok(r, run["nodes"][u]["status"]) for u, r in edges]
            join_mode = (nodes[nid].get("join") or "all")
            return any(sat) if join_mode == "any" else all(sat)
        def doomed(nid):
            if run["nodes"][nid]["status"] != "pending": return False
            edges = ins.get(nid, [])
            if not edges: return False
            possible = [not _edge_dead(r, run["nodes"][u]["status"]) for u, r in edges]
            join_mode = (nodes[nid].get("join") or "all")
            return not (any(possible) if join_mode == "any" else all(possible))
        for nid, rec in run["nodes"].items():
            if rec["status"] == "pending" and doomed(nid):
                rec["status"] = "skipped"; rec["error"] = "按连线路由,上游结果不满足本节点的触发条件"
        store.save_run(run)
        ready = [nid for nid in run["nodes"] if ready_check(nid)]
        running = [nid for nid, rec in run["nodes"].items() if rec["status"] == "running"]
        if ready and len(running) < 8:
            for nid in ready[: 8 - len(running)]:
                run["nodes"][nid]["status"] = "running"
                asyncio.get_event_loop().create_task(exec_node(nid))
            store.save_run(run)
        elif not ready and not running:
            if any(r["status"] == "failed" for r in run["nodes"].values()):
                run["status"] = "failed"; run["error"] = "存在失败的节点"
            elif any(r["status"] == "stopped" for r in run["nodes"].values()):
                run["status"] = "stopped"
            else:
                run["status"] = "done"
            break
        await asyncio.sleep(1.0)
    run["ended_at"] = _ms()
    if run["status"] == "running": run["status"] = "failed"
    store.save_run(run)
